import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<{name:string,params:any,trigger:string}>} [cinematicPrimitives]
 * @property {Array<{text:string,role:string,typography?:{fontSize?:number}}>} [textContent]
 * @property {Array<number>} [rotation]
 * @property {Array<number>} [scale]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {any} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const group = new Group();

  // Plane geometry sized to atlas region aspect ratio (512:320 = 1.6:1)
  const aspect = 512 / 320;
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // Basic node material (transparent to allow any alpha in texture)
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load texture asynchronously via ctx loader (but keep function sync)
  let loadedTexture = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    loadedTexture = tex;
    material.map = tex;
    material.needsUpdate = true;
  });

  // Apply rotation and scale from config (position is applied by adapter)
  if (Array.isArray(config.rotation)) {
    group.rotation.set(...config.rotation);
  }
  if (Array.isArray(config.scale)) {
    group.scale.set(...config.scale);
  }

  // Apply any cinematic primitives listed in config
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const name = prim.name;
      const params = prim.params || {};
      if (ctx.primitives && typeof ctx.primitives[name] === 'function') {
        const handle = ctx.primitives[name](group, params);
        primitiveHandles.push(handle);
      }
    }
  }

  // Render any text items via fontAtlas (none in this spec, but keep logic)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txtOpts = {
      fontSize: item.typography?.fontSize,
      color: '#e8ecf2',
      align: 'left',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, txtOpts);
    group.add(txtObj);
  }

  // Billboard handler – called by the runtime each frame with the active camera
  group.userData.handlers = {
    update: (camera) => {
      // Keep the plane facing the camera
      group.lookAt(camera.position);
    },
  };

  // Cleanup resources and kill any timelines
  group.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // Dispose loaded texture
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
    }
    // Kill any GSAP timelines (none created here but safe)
    gsap.globalTimeline.clear();
  };

  return group;
}
